<?php $mode=$data['receiptMode'];$r=$data['receipt']??null;?>
<div class="module-stack"><?php if(!empty($data['notice'])):?><div class="alert alert-success"><?=e($data['notice']['message']??'Completed.')?></div><?php endif;?><?php foreach((array)($data['errors']??[]) as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?>
<nav class="card"><a class="btn btn-secondary" href="/office_app/public/inventory">Inventory</a><a class="btn btn-secondary" href="/office_app/public/inventory/receipts">Receipts</a><a class="btn btn-secondary" href="/office_app/public/data-exchange/receipts/export/configure">Export</a><?php if(!empty($data['canCreate'])):?><a class="btn btn-primary" href="/office_app/public/inventory/receipts/create">New Receipt</a><?php endif;?></nav>
<?php if($mode==='list'):?><section class="card table-card"><h2>Goods receipts</h2><table class="data-table"><thead><tr><th>Receipt</th><th>Warehouse</th><th>Vendor</th><th>Date</th><th>Quantity</th><th>Value</th><th>Status</th></tr></thead><tbody><?php if($data['receipts']===[]):?><tr><td colspan="7">No goods receipts.</td></tr><?php endif;?><?php foreach($data['receipts'] as $row):?><tr><td><a href="/office_app/public/inventory/receipts/<?=e($row['goods_receipt_id'])?>"><?=e($row['receipt_number'])?></a></td><td><?=e($row['warehouse_name'])?></td><td><?=e($row['supplier_name']??'')?></td><td><?=e($row['receipt_date'])?></td><td><?=e($row['total_quantity'])?></td><td><?=e($row['currency'].' '.number_format((float)$row['total_value'],2))?></td><td><?=e($row['status'])?></td></tr><?php endforeach;?></tbody></table></section>
<?php elseif($mode==='create'):?><section class="card"><h2>New goods receipt</h2><p>Posting receives goods through Vendors → Input and automatically puts them away Input → Stock.</p><form method="post" action="/office_app/public/inventory/receipts"><?=csrfField()?><div class="finance-filter-form"><label>Warehouse<select name="warehouse_id" required><option value="">Select warehouse</option><?php foreach($data['options']['warehouses'] as $w):?><option value="<?=e($w['warehouse_id'])?>"><?=e($w['name'].' / '.$w['code'])?></option><?php endforeach;?></select></label><label>Vendor/source<input name="supplier_name" required></label><label>Vendor reference<input name="supplier_reference"></label><label>Receipt date<input type="date" name="receipt_date" value="<?=e(date('Y-m-d'))?>" required></label><label>Currency<input name="currency" value="ETB" maxlength="3" required></label></div><table class="data-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit cost</th></tr></thead><tbody><tr><td><select name="product_id[]" required><option value="">Select product</option><?php foreach($data['options']['products'] as $p):?><option value="<?=e($p['product_id'])?>"><?=e($p['sku'].' - '.$p['name'])?></option><?php endforeach;?></select></td><td><input type="number" name="quantity[]" min="0.001" step="0.001" required></td><td><input type="number" name="unit_cost[]" min="0" step="0.000001" value="0" required></td></tr></tbody></table><label>Notes<textarea name="notes"></textarea></label><button class="btn btn-primary">Save Receipt</button></form></section>
<?php else:?><section class="card"><p><strong>Warehouse:</strong> <?=e($r['warehouse_name'])?> · <strong>Vendor:</strong> <?=e($r['supplier_name']??'')?> · <strong>Status:</strong> <?=e($r['status'])?></p><p><strong>Route:</strong> <?=e($r['operation_code'])?> · <?=e($r['source_location_name'])?> → <?=e($r['receipt_location_name'])?> → Stock</p><?php if($r['status']==='draft'&&!empty($data['canApprove'])):?><form method="post" action="/office_app/public/inventory/receipts/<?=e($r['goods_receipt_id'])?>/approve"><?=csrfField()?><button class="btn btn-primary">Approve Receipt</button></form><?php elseif($r['status']==='approved'&&!empty($data['canPost'])):?><form method="post" action="/office_app/public/inventory/receipts/<?=e($r['goods_receipt_id'])?>/post"><?=csrfField()?><button class="btn btn-primary">Post Receipt</button></form><?php endif;?></section><section class="card table-card"><h2>Receipt lines</h2><table class="data-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit cost</th><th>Value</th></tr></thead><tbody><?php foreach($r['lines'] as $line):?><tr><td><?=e($line['sku'].' - '.$line['product_name'])?></td><td><?=e($line['quantity'])?></td><td><?=e($line['unit_cost'])?></td><td><?=e($line['line_value'])?></td></tr><?php endforeach;?></tbody></table></section><section class="card table-card"><h2>Movement history</h2><table class="data-table"><thead><tr><th>Movement</th><th>From</th><th>To</th><th>Quantity</th><th>Status</th></tr></thead><tbody><?php if($r['movements']===[]):?><tr><td colspan="5">No movements until the receipt is posted.</td></tr><?php endif;?><?php foreach($r['movements'] as $m):?><tr><td><?=e(str_replace('_',' ',$m['movement_type']))?></td><td><?=e($m['source_location_name']??'External')?></td><td><?=e($m['destination_location_name']??'External')?></td><td><?=e($m['completed_quantity'])?></td><td><?=e($m['status'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?></div>
